#!/usr/bin/env bash
set -euo pipefail
DB_URL="${DATABASE_URL:-postgresql://postgres:postgres@127.0.0.1:5432/postgres}"; PSQL=(psql "$DB_URL" -X -v ON_ERROR_STOP=1)
pass(){ printf 'PASS: %s\n' "$1"; }; fail(){ printf 'FAIL: %s\n' "$1" >&2; exit 1; }; run(){ "${PSQL[@]}" -qAtc "$1"; }
expect_value(){ local label="$1" sql="$2" expected="$3" actual; actual="$(run "$sql")"; [[ "$actual" == "$expected" ]]||fail "$label (expected '$expected', got '$actual')"; pass "$label"; }
expect_fail(){ local label="$1" sql="$2"; if "${PSQL[@]}" -qc "$sql" >/tmp/nilai-db-out 2>/tmp/nilai-db-err;then fail "$label (unexpected success)";fi;pass "$label";}
"${PSQL[@]}" -f supabase/migrations/202609040006_bulk_assessment.sql >/dev/null
A="set role authenticated; set request.jwt.claims = '{\"sub\":\"00000000-0000-0000-0000-00000000000a\",\"role\":\"authenticated\"}';"; ANON="set role anon;set request.jwt.claims='{\"role\":\"anon\"}';"; AW="(select id from public.workspaces where owner_user_id='00000000-0000-0000-0000-00000000000a')"; ASSESS="9a000000-0000-0000-0000-000000000001"; E1="9b000000-0000-0000-0000-000000000001";E2="9b000000-0000-0000-0000-000000000002";E3="9b000000-0000-0000-0000-000000000003";OP="9c000000-0000-0000-0000-000000000001"
run "$A insert into public.assessments(id,workspace_id,class_id,academic_period_id,title) values('$ASSESS',$AW,'30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','Bulk Test'); insert into public.students(id,workspace_id,display_name,nis) values('9d000000-0000-0000-0000-000000000001',$AW,'Nama Sama','B01'),('9d000000-0000-0000-0000-000000000002',$AW,'Nama Sama','B02'),('9d000000-0000-0000-0000-000000000003',$AW,'Tiga','B03'); insert into public.enrollments(id,workspace_id,student_id,class_id) values('$E1',$AW,'9d000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001'),('$E2',$AW,'9d000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000001'),('$E3',$AW,'9d000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000001');" >/dev/null
ROWS="[{\"enrollment_id\":\"$E1\",\"state\":\"GRADED\",\"score\":0,\"expected_revision\":0,\"attempt_kind\":\"CORRECTION\",\"raw_score\":0},{\"enrollment_id\":\"$E2\",\"state\":\"GRADED\",\"score\":-5,\"expected_revision\":0,\"attempt_kind\":\"CORRECTION\",\"raw_score\":-5},{\"enrollment_id\":\"$E3\",\"state\":\"MISSING\",\"score\":null,\"expected_revision\":0,\"attempt_kind\":null,\"raw_score\":null}]"
expect_value 'atomic bulk saves zero negative and Missing' "$A select outcome||':'||replayed from public.apply_assessment_bulk_operation('$OP','$ASSESS','$ROWS');" 'saved:false'
expect_value 'canonical batch semantics exact' "$A select string_agg(enrollment_id::text||':'||state||':'||coalesce(score::text,'NULL')||':'||revision,',' order by enrollment_id) from public.assessment_results where assessment_id='$ASSESS';" "$E1:GRADED:0:1,$E2:GRADED:-5:1,$E3:MISSING:NULL:1"
expect_value 'bulk Attempts created only for graded writes' "$A select count(*) from public.assessment_attempts where result_id in(select id from public.assessment_results where assessment_id='$ASSESS');" '2'
expect_value 'lost ACK same op replays' "$A select outcome||':'||replayed from public.apply_assessment_bulk_operation('$OP','$ASSESS','$ROWS');" 'saved:true'
expect_value 'replay creates no duplicate Attempts' "$A select count(*) from public.assessment_attempts where result_id in(select id from public.assessment_results where assessment_id='$ASSESS');" '2'
expect_fail 'changed payload cannot reuse bulk op id' "$A select * from public.apply_assessment_bulk_operation('$OP','$ASSESS','[{\"enrollment_id\":\"$E1\",\"state\":\"GRADED\",\"score\":9,\"expected_revision\":1}]');"
expect_fail 'duplicate Enrollment row fails closed' "$A select * from public.apply_assessment_bulk_operation('9c000000-0000-0000-0000-000000000002','$ASSESS','[{\"enrollment_id\":\"$E1\",\"state\":\"GRADED\",\"score\":1,\"expected_revision\":1},{\"enrollment_id\":\"$E1\",\"state\":\"GRADED\",\"score\":2,\"expected_revision\":1}]');"
run "$A select * from public.apply_assessment_judgement_operation('9c000000-0000-0000-0000-000000000003','$ASSESS','$E1','GRADED',7,'CORRECTION',7,'{}',1);" >/dev/null
STALE="[{\"enrollment_id\":\"$E1\",\"state\":\"GRADED\",\"score\":8,\"expected_revision\":1},{\"enrollment_id\":\"$E2\",\"state\":\"EXCUSED\",\"score\":null,\"expected_revision\":1}]"
expect_value 'one stale row conflicts whole batch with canonical truth' "$A select outcome||':'||(conflicts->0->>'canonical_revision')||':'||(conflicts->0->>'canonical_state')||':'||(conflicts->0->>'canonical_score') from public.apply_assessment_bulk_operation('9c000000-0000-0000-0000-000000000004','$ASSESS','$STALE');" 'conflict:2:GRADED:7'
expect_value 'conflict causes zero mutation to otherwise current row' "$A select state||':'||score||':'||revision from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$E2';" 'GRADED:-5:1'
BAD="[{\"enrollment_id\":\"$E2\",\"state\":\"GRADED\",\"score\":11,\"expected_revision\":1},{\"enrollment_id\":\"$E3\",\"state\":\"GRADED\",\"score\":12,\"expected_revision\":1,\"attempt_kind\":\"BAD\"}]"
expect_fail 'database failure during batch rolls back entire transaction' "$A select * from public.apply_assessment_bulk_operation('9c000000-0000-0000-0000-000000000005','$ASSESS','$BAD');"
expect_value 'rollback preserved first row canonical truth' "$A select state||':'||score||':'||revision from public.assessment_results where assessment_id='$ASSESS' and enrollment_id='$E2';" 'GRADED:-5:1'
expect_fail 'foreign workspace Enrollment rejected' "$A select * from public.apply_assessment_bulk_operation('9c000000-0000-0000-0000-000000000006','$ASSESS','[{\"enrollment_id\":\"94000000-0000-0000-0000-000000000001\",\"state\":\"GRADED\",\"score\":1,\"expected_revision\":0}]');"
expect_fail 'anonymous cannot execute bulk RPC' "$ANON select * from public.apply_assessment_bulk_operation('9c000000-0000-0000-0000-000000000007','$ASSESS','[]');"
expect_value 'one bulk ledger row only for committed op' "$A select count(*) from public.applied_operations where operation_type='assessment.bulk' and target_entity_id='$ASSESS';" '1'
expect_value 'schema version is bulk assessment' "$A select version from public.app_schema_version where id=1;" 'r3.3-bulk-assessment.1'
printf '\nR3.3 Bulk Assessment PostgreSQL contract matrix completed successfully.\n'
